window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-28-observability-amp-br-operations"]={"html":"Observability &amp; Operations — Kubernetes Book 07\n\n\n<a href=\"#toc\">▤ TOC</a>\n\n\n<div class=\"page cover\">\n<div class=\"orb\"></div>\n<div class=\"orb\"></div>\n<div class=\"wheel\">🔭</div>\n<h1 id=\"observability-amp-operations\">OBSERVABILITY &amp;<br />OPERATIONS</h1>\n<div class=\"sub\">Book 07 of the series — knowing what your cluster is doing: Probes (the health question Kubernetes can't answer alone), Metrics Server &amp; Prometheus, the exporter cast, log architecture &amp; Loki, Grafana, PromQL/LogQL, events &amp; audit — and the cluster-wide failure playbook.</div>\n<div class=\"row\">\n<div class=\"glass\">🩺 Probes<small>liveness · readiness</small></div>\n<div class=\"glass\">📈 Metrics<small>server · top</small></div>\n<div class=\"glass\">🔥 Prometheus<small>pull model</small></div>\n<div class=\"glass\">🛰️ Exporters<small>node · state · cAd</small></div>\n</div>\n<div class=\"row\">\n<div class=\"glass\">📜 Logs<small>/var/log/pods</small></div>\n<div class=\"glass\">🪵 Loki<small>labels only</small></div>\n<div class=\"glass\">📊 Grafana<small>the pane</small></div>\n<div class=\"glass\">🚑 Playbook<small>cluster triage</small></div>\n</div>\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 07 · CONTINUES BOOKS 01–06 · 2026</div>\n</div>\n\n\n<div class=\"page\">\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">7 parts · 23 chapters</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part I · Probes — The Health Question</div>\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>Running ≠ Healthy<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>Liveness Probes — Restart the Stuck<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>Readiness — The Traffic Gate<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>Startup Probes &amp; Probe Mechanics<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\n<div class=\"tocpart\">Part II · Metrics</div>\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Metrics Server &amp; kubectl top<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>Prometheus — The Pull Model<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>The Exporter Cast — Who Exposes What<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\n<div class=\"tocpart\">Part III · Logs</div>\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>Where Logs Actually Live<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>Collection Patterns — DaemonSet · Sidecar<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>Loki — Prometheus for Logs<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\n<div class=\"tocpart\">Part IV · See It &amp; Query It</div>\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>Grafana — The Unified Pane<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\n<a href=\"#ch12\"><span class=\"cb\"></span><span class=\"tnum\">CH 12</span>PromQL &amp; LogQL — First Queries<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\n<div class=\"tocpart\">Part V · Operations</div>\n<a href=\"#ch13\"><span class=\"cb\"></span><span class=\"tnum\">CH 13</span>Events &amp; Audit Logging<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\n<a href=\"#ch14\"><span class=\"cb\"></span><span class=\"tnum\">CH 14</span>The Cluster-Scope Failure Playbook<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\n<div class=\"tocpart\">Part VI · Labs</div>\n<a href=\"#lab1\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>Probes That Bite<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<a href=\"#lab2\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>Top &amp; Events Triage<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\n<a href=\"#lab3\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>Install the Stack (Helm Preview)<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\n<a href=\"#lab4\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>Query Everything<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\n<div class=\"tocpart\">Part VII · Prove It</div>\n<a href=\"#quiz\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\n<a href=\"#key\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\n<a href=\"#gloss\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.23</span></a>\n<a href=\"#cheat\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.24</span></a>\n<a href=\"#finale\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>Where to Next → Book 08<span class=\"dots\"></span><span class=\"tp\">p.25</span></a>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Assumes Books 01–06.</b> Book 01's self-healing restarts <b>dead</b> processes — this book's Part I handles the ones that are <i>alive but broken</i>. Book 06's HPA already ate from metrics-server; now you meet the whole kitchen. Your DaemonSet agents (Book 06 · CH 01) return as the log collectors.</div></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span>◀ cover · start ▶</span><span>Page 2</span></div>\n</div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"running-healthy\">🩺 Running ≠ Healthy</h2><span class=\"dbadge\">🟢 4 MIN · THE HOLE</span></div>\n<p>Book 01 · CH 06 taught self-healing: a Pod dies → reconciliation replaces it. But look closer at what triggers it — <b>process death</b>. A deadlocked, memory-leaking, or infinitely-hung application never dies. It just keeps <span class=\"stbadge st-run\">Running</span>. Forever. Serving garbage.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">Without probes — the lie of the STATUS column</div>\n<div class=\"term mini\"><span class=\"y\">NAME     STATUS   RESTARTS</span>\napi-7d9f  <span class=\"p\">Running</span>  0   <span class=\"g\"># looks perfect…</span>\n<span class=\"g\"># reality: deadlocked since Tuesday.\n# holds connections open, serves timeouts.\n# self-healing will NEVER touch it —\n# the process is alive. k8s can't see\n# \"working\" — only \"not crashed\".</span></div></div>\n<div class=\"card\">\n<div class=\"zlabel\">With probes — you teach k8s what \"healthy\" means</div>\n<div class=\"term mini\"><span class=\"y\">NAME     STATUS   RESTARTS</span>\napi-x7k2 <span class=\"p\">Running</span>  <span class=\"y\">37</span>  <span class=\"g\"># restarts = the probe\n# KILLING broken containers.\n# 37 restarts looks scary —\n# it's the system working.</span></div></div>\n</div>\n<h3 id=\"the-three-pillars-this-book-covers-and-the-fourth\">🔭 The three pillars this book covers (and the fourth)</h3>\n<div class=\"rowc\">\n<div class=\"kchip\">📈 <b>Metrics</b><small> how much / how fast</small></div>\n<div class=\"kchip\">📜 <b>Logs</b><small> what happened, exactly</small></div>\n<div class=\"kchip\">🩺 <b>Probes</b><small> is it working NOW</small></div>\n<div class=\"kchip\">🔗 <b>Traces</b><small> where time went — Book 09's horizon</small></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Probes vs monitoring:</b> probes are <b>reflexes</b> — automated, per-Pod, inside the cluster (restart / gate traffic). Metrics and logs are <b>awareness</b> — stored, queried, human-facing. You need both; reflexes without awareness is a body that heals but never learns.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Kubernetes can only see <b>life</b> (the process runs) — probes are how you teach it to see <b>health</b> (the process works), and they come in exactly two flavors of consequence: <b>restart it</b> (liveness) or <b>don't send traffic</b> (readiness) — next two chapters.</div></div>\n<p>⏭️ The restart reflex — <a href=\"#ch02\">CH 02: Liveness Probes</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"liveness-probes-restart-the-stuck\">💀 Liveness Probes — Restart the Stuck</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A liveness probe asks one question on a timer: <i>\"are you working?\"</i> Fail it enough times and the <b>kubelet kills the container</b> — and the restart policy (Book 01) brings it back fresh. Deadlock → cured by machine, not by 3am pager.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">containers</span>:\n  - <span class=\"c\">name</span>: api\n    <span class=\"c\">image</span>: myapi:2.0\n    <span class=\"c\">livenessProbe</span>:\n      <span class=\"c\">httpGet</span>:\n        <span class=\"c\">path</span>: <span class=\"m\">/healthz</span>       <span class=\"g\"># YOUR endpoint — cheap, local, self-contained</span>\n        <span class=\"c\">port</span>: <span class=\"y\">8080</span>\n      <span class=\"c\">initialDelaySeconds</span>: <span class=\"y\">10</span>  <span class=\"g\"># let the app boot first</span>\n      <span class=\"c\">periodSeconds</span>: <span class=\"y\">10</span>        <span class=\"g\"># ask every 10s</span>\n      <span class=\"c\">failureThreshold</span>: <span class=\"y\">3</span>      <span class=\"g\"># 3 consecutive fails → RESTART</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🔍 Four ways to ask</div>\n<div class=\"table-scroll\"><table><tr><th>Mechanism</th><th>Healthy when…</th></tr>\n<tr><td><code>httpGet</code></td><td>response <b>200–399</b></td></tr>\n<tr><td><code>tcpSocket</code></td><td>TCP connect succeeds</td></tr>\n<tr><td><code>exec</code></td><td>command exits <b>0</b></td></tr>\n<tr><td><code>grpc</code></td><td>gRPC health check passes</td></tr></table></div></div>\n<div class=\"card\"><div class=\"zlabel\">⚙️ The timing knobs</div>\n<div class=\"term mini\"><span class=\"c\">initialDelaySeconds</span>  <span class=\"g\">grace before first check</span>\n<span class=\"c\">periodSeconds</span>        <span class=\"g\">ask interval (default 10)</span>\n<span class=\"c\">timeoutSeconds</span>       <span class=\"g\">answer deadline (default 1)</span>\n<span class=\"c\">failureThreshold</span>     <span class=\"g\">consecutive fails → act</span>\n<span class=\"c\">successThreshold</span>     <span class=\"g\">fails needed to heal\n(liveness: always 1)</span></div></div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The #1 liveness mistake — checking dependencies:</b> if <code>/healthz</code> verifies \"can I reach the database?\", then one DB blip makes <b>every Pod's liveness fail</b> → the entire fleet restart-loops <i>simultaneously</i> — you converted a database hiccup into a self-inflicted full outage. Liveness = <b>am I functional?</b> (process, event loop, local state) — <b>never</b> \"are my friends up?\"</div></div>\n<ul>\n<li>💸 Probes run constantly — keep them <b>cheap</b>: a 2-second liveness check every 10s on 200 Pods is real load</li>\n<li>🔁 Restarts use the <b>crash backoff</b> (10s, 20s, 40s… capped 5 min) — pathological flapping shows as growing RESTARTS + CrashLoopBackOff rhythm (Book 01 · CH 23)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> a liveness probe is a <b>dead-man's switch for the walking dead</b> — it lets the kubelet kill what should be dead but isn't, and its cardinal rule is <i>check yourself, never your dependencies</i>. Lab 1 pulls the trigger on purpose.</div></div>\n<p>⏭️ The gentler sibling — <a href=\"#ch03\">CH 03: Readiness</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"readiness-the-traffic-gate\">🚦 Readiness — The Traffic Gate</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Liveness answers \"keep or kill?\" — readiness answers a different question entirely: <b>\"send this Pod customers right now?\"</b> A failing readiness probe restarts <i>nothing</i>; it just removes the Pod from the Service's endpoints (Book 03 · CH 11 machinery).</p>\n<div class=\"term\"><span class=\"c\">livenessProbe</span>:\n  <span class=\"c\">httpGet</span>: { <span class=\"c\">path</span>: <span class=\"m\">/healthz</span>, <span class=\"c\">port</span>: <span class=\"y\">8080</span> }\n<span class=\"c\">readinessProbe</span>:\n  <span class=\"c\">httpGet</span>: { <span class=\"c\">path</span>: <span class=\"m\">/ready</span>, <span class=\"c\">port</span>: <span class=\"y\">8080</span> }\n  <span class=\"c\">periodSeconds</span>: <span class=\"y\">5</span>\n  <span class=\"c\">failureThreshold</span>: <span class=\"y\">2</span>     <span class=\"g\"># pull from rotation fast</span>\n  <span class=\"c\">successThreshold</span>: <span class=\"y\">1</span>     <span class=\"g\"># but return instantly when it recovers</span></div>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">What a failing readiness probe actually does</div>\n<div class=\"rowc\">\n<div class=\"pod\">🫛 web-1<small>Ready ✓</small></div>\n<div class=\"pod\">🫛 web-2<small><span class=\"r\">NotReady</span> — gated</small></div>\n</div>\n<div class=\"dn\">▼ Service selector gathers endpoints ▼</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get endpoints web\n<span class=\"y\">NAME  ENDPOINTS</span>\nweb   <span class=\"p\">10.244.1.5:8080</span>  <span class=\"g\"># web-2 GONE from the list —\n                      # no restarts, no logs, just no traffic</span></div>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th></th><th>🩺 Liveness</th><th>🚦 Readiness</th></tr>\n<tr><td><b>Question</b></td><td>are you alive, or kill you?</td><td>should traffic reach you?</td></tr>\n<tr><td><b>On failure</b></td><td><b>container RESTARTED</b></td><td><b>removed from endpoints</b> — nothing else</td></tr>\n<tr><td><b>Recovers by</b></td><td>fresh process</td><td>probe passing again — instant re-admission</td></tr>\n<tr><td><b>Use for</b></td><td>deadlocks, hopeless states</td><td>warming caches, loading models, <b>overload shedding</b>, DB reconnection</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Rolling updates already depended on this:</b> Book 01 · CH 20's \"new Pod replaces old only when Ready\" — <i>Ready means the readiness probe passes</i>. No readiness probe = rolling update slams traffic into Pods that are still booting. This chapter is where that story gets its ending.</div></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The readiness death-spiral check:</b> readiness <i>may</i> include dependencies (\"can I reach my DB? — if not, shed traffic\") where liveness may not. Readiness failing everywhere is <b>safe</b> (traffic stops, pods survive, users see errors) — but ensure something restarts or alerts, because a Pod can sit NotReady <b>forever</b> and Kubernetes will not lift a finger.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> readiness is a <b>traffic valve, not a kill switch</b> — failing pods drop out of the endpoints list silently and rejoin when ready, which is what makes rolling updates, warm-ups, and overload survival possible.</div></div>\n<p>⏭️ The boot-guard for slow apps — <a href=\"#ch04\">CH 04: Startup Probes</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 5</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"startup-probes-amp-probe-mechanics\">🐣 Startup Probes &amp; Probe Mechanics</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>Some apps boot slowly — a JVM loading 4GB of heap, a model loading weights. Liveness starts checking at <code>initialDelaySeconds</code>… and if the app needs 90 seconds, you either set a huge delay (slow restarts forever) or watch it <b>restart-loop during every boot</b>. The startup probe solves the dilemma: <b>it disables the other probes until the app is up once.</b></p>\n<div class=\"term\"><span class=\"c\">startupProbe</span>:                    <span class=\"g\"># runs FIRST — liveness/readiness wait</span>\n  <span class=\"c\">httpGet</span>: { <span class=\"c\">path</span>: <span class=\"m\">/healthz</span>, <span class=\"c\">port</span>: <span class=\"y\">8080</span> }\n  <span class=\"c\">failureThreshold</span>: <span class=\"y\">30</span>           <span class=\"g\"># 30 × 10s = up to 5 minutes to boot</span>\n  <span class=\"c\">periodSeconds</span>: <span class=\"y\">10</span>\n<span class=\"c\">livenessProbe</span>:                    <span class=\"g\"># takes over ONLY after startup succeeds</span>\n  <span class=\"c\">httpGet</span>: { <span class=\"c\">path</span>: <span class=\"m\">/healthz</span>, <span class=\"c\">port</span>: <span class=\"y\">8080</span> }\n  <span class=\"c\">periodSeconds</span>: <span class=\"y\">10</span>\n  <span class=\"c\">failureThreshold</span>: <span class=\"y\">3</span></div>\n<div class=\"mtree\"><b>Boot sequence with all three probes:</b>\ncontainer starts ──► <u>startupProbe</u> asks every 10s\n      │ one success (or 30 fails → container killed)\n      ▼\n<u>readiness</u> + <u>liveness</u> activate from this moment\n      ├── readiness fails → out of endpoints (traffic gate)\n      └── liveness fails  → RESTART (and startup runs again first!)</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Probe</th><th>Fires</th><th>On failure</th><th>One-line job</th></tr>\n<tr><td><b>startup</b></td><td>from container start</td><td>restart (after threshold)</td><td>guard the boot — protect slow starters from eager liveness</td></tr>\n<tr><td><b>readiness</b></td><td>after startup passes</td><td>out of endpoints</td><td>gate traffic per moment</td></tr>\n<tr><td><b>liveness</b></td><td>after startup passes</td><td>restart container</td><td>kill the undead</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Rule of thumb:</b> fast-booting app → skip startupProbe, use <code>initialDelaySeconds</code>. Slow or variable boot → startupProbe with generous <code>failureThreshold × periodSeconds</code> budget, and tight liveness afterwards. Best of both: instant restart detection <i>and</i> no boot-looping.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the startup probe is a <b>one-shot gate that silences the other probes until first success</b> — letting slow apps boot in peace while keeping restart-reflexes razor-sharp once they're up. All three together = the complete health contract. Lab 1 fires all of them.</div></div>\n<p>⏭️ Part II: from reflexes to awareness — <a href=\"#ch05\">CH 05: Metrics Server</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 6</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"metrics-server-amp-kubectl-top\">📊 Metrics Server &amp; kubectl top</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>The lightest rung of the metrics ladder: <b>metrics-server</b> — a small in-cluster component that scrapes resource usage from every kubelet and serves it through the Metrics API. It's what makes <code>kubectl top</code> work and what fed Book 06's HPA.</p>\n<div class=\"term\"><span class=\"p\">$</span> minikube addons enable metrics-server\n<span class=\"p\">$</span> kubectl top nodes\n<span class=\"y\">NAME      CPU(cores)  CPU%   MEMORY(bytes)  MEMORY%</span>\nminikube  347m        17%    1823Mi         47%\n<span class=\"p\">$</span> kubectl top pods -n shop\n<span class=\"y\">NAME     CPU(cores)  MEMORY(bytes)</span>\nweb-x7k2 <span class=\"r\">480m</span>       210Mi  <span class=\"g\"># vs its REQUEST (Book 02 · CH 14) — 96% of 500m!</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Know its ceiling:</b> metrics-server keeps only the <b>latest ~15 minutes</b> of samples. No history, no graphs, no alerts, no dashboards. It answers \"how much is it using <i>right now</i>?\" — long-term awareness is Prometheus's job (CH 06). <code>top</code> numbers also lag reality by ~1 minute (scrape + aggregation).</div></div>\n<ul>\n<li>🔗 <b>Its two customers:</b> <code>kubectl top</code> (you) and the <b>HPA's <code>Resource</code> metrics</b> (Book 06 · CH 07) — no metrics-server, no autoscaling on cpu/memory</li>\n<li>🧮 <code>top</code> shows <b>actual usage</b>; compare against <code>requests</code> to spot right-sizing candidates — that comparison is exactly what VPA automates (Book 06 · CH 08)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> metrics-server is the <b>short-term pulse</b> — live CPU/memory per node and Pod for <code>top</code> and the HPA, deliberately keeping nothing older than minutes; everything beyond that is Prometheus's territory, next chapter.</div></div>\n<p>⏭️ The real memory — <a href=\"#ch06\">CH 06: Prometheus</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 7</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"prometheus-the-pull-model\">🔥 Prometheus — The Pull Model</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Prometheus is the de-facto metrics database of the Kubernetes world. Its defining choice: it <b>pulls</b> — it scrapes each target's <code>/metrics</code> HTTP endpoint on an interval, storing every measurement as a <b>time series</b>.</p>\n<div class=\"term\"><span class=\"g\"># a target's /metrics endpoint is just text — self-describing:</span>\n<span class=\"p\">$</span> curl localhost:8080/metrics\n<span class=\"c\">http_requests_total</span>{method=<span class=\"m\">\"POST\"</span>,code=<span class=\"m\">\"200\"</span>} <span class=\"y\">1027</span>\n<span class=\"c\">http_request_duration_seconds</span>{quantile=<span class=\"m\">\"0.99\"</span>} <span class=\"y\">0.14</span>\n<span class=\"g\"># metric NAME + LABELS (dimensions) + current VALUE —\n# scraped over time, each combo becomes a time series</span></div>\n<div class=\"grid3\">\n<div class=\"card\"><p><b>🗄️ Time Series</b><br />name + labels + timestamped values — the only data shape. Labels are the dimensions you'll slice by.</p></div>\n<div class=\"card\"><p><b>🔍 PromQL</b><br />query language built for rates, aggregation, and math over series (CH 12).</p></div>\n<div class=\"card\"><p><b>🚨 Alerting</b><br />PromQL conditions → <b>Alertmanager</b> → Slack/PagerDuty/email routing.</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Why pull wins here:</b> the scraper controls the pace and the target list; apps just expose <code>/metrics</code> and need zero knowledge of where Prometheus lives. Bonus: a dead target doesn't vanish — its <code>up</code> metric becomes <b>0</b>, so <i>you can query whether the monitoring itself sees the target</i>: <code>up == 0</code> is the oldest trick in the Prometheus book.</div></div>\n<div class=\"zone zone-cp\">\n<div class=\"zlabel\">In a cluster — who watches the watchers</div>\n<div class=\"rowc\">\n<div class=\"nb c-slate\">🔥 Prometheus<small>Deployment in ns mon</small></div>\n<span class=\"harr\">──scrape──►</span>\n<div class=\"pod\">🫛 /metrics</div>\n<div class=\"pod\">🫛 /metrics</div>\n<div class=\"nb c-amber\">🖥️ /metrics<small>node-exporter</small></div>\n</div>\n<p>target discovery is automatic — via Service discovery + <b>ServiceMonitor/PodMonitor CRDs</b> (next chapter), never hand-maintained IP lists</p>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Prometheus = <b>pull-based time-series machine</b> — it scrapes self-describing <code>/metrics</code> endpoints, keeps every label-combination as its own series, answers with PromQL, and even reports its own blindness via <code>up == 0</code>.</div></div>\n<p>⏭️ Where all those endpoints come from — <a href=\"#ch07\">CH 07: The Exporter Cast</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 8</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"the-exporter-cast-who-exposes-what\">🛰️ The Exporter Cast — Who Exposes What</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Prometheus only scrapes — someone must <b>expose</b> the numbers. Three built-in exporters cover the whole cluster, each answering a different \"is it healthy?\" question:</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Exporter</th><th>Runs as</th><th>Exposes</th><th>Answers</th></tr>\n<tr><td>🖥️ <b>node-exporter</b></td><td><b>DaemonSet</b> (Book 06 · CH 01!)</td><td>host-level: CPU, memory, disk, network of the <b>machine</b></td><td>\"is the <i>machine</i> healthy?\"</td></tr>\n<tr><td>⚙️ <b>cAdvisor</b></td><td>embedded in the <b>kubelet</b></td><td>per-container actual usage: CPU, memory, restarts</td><td>\"which <i>container</i> eats resources?\"</td></tr>\n<tr><td>📦 <b>kube-state-metrics</b></td><td>Deployment, watches the <b>API Server</b></td><td>object states: replicas desired vs ready, pending pods, PVC capacity</td><td>\"does <i>Kubernetes</i> think all is well?\"</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>The layer trick:</b> the same Pod can be healthy in all three views at once — or exactly one. High node CPU (node-exporter) + low pod CPU (cAdvisor) = something else on the machine. Pod Running + <code>kube_pod_status_phase{phase=\"Pending\"}</code> climbing (kube-state-metrics) = scheduling trouble (Book 04!). Three lenses, one truth.</div></div>\n<h3 id=\"servicemonitor-declarative-scrape-config\">🎯 ServiceMonitor — declarative scrape config</h3>\n<div class=\"term mini\"><span class=\"c\">apiVersion</span>: monitoring.coreos.com/v1        <span class=\"g\"># a CRD — Book 08 previews CRDs</span>\n<span class=\"c\">kind</span>: ServiceMonitor\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: web, <span class=\"c\">labels</span>: { <span class=\"c\">release</span>: mon } }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">selector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: web } }\n  <span class=\"c\">endpoints</span>: [{ <span class=\"c\">port</span>: <span class=\"y\">metrics</span> }]\n<span class=\"g\"># \"scrape any Service labeled app=web at port `metrics`\" —\n# deploy your app WITH its ServiceMonitor → deploy = monitored (Book 02 · CH 04b pattern)</span></div>\n<div class=\"term mini\"><span class=\"p\">$</span> helm install mon prometheus-community/kube-prometheus-stack\n<span class=\"g\"># one chart = Prometheus + Alertmanager + Grafana +\n# node-exporter (DS) + kube-state-metrics + the CRDs — the full bundle</span></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> cluster metrics come from a three-layer cast — <b>node-exporter (machines, per node), cAdvisor (containers, via kubelet), kube-state-metrics (object states, via API)</b> — and your own apps join by exposing <code>/metrics</code> plus a ServiceMonitor CRD.</div></div>\n<p>⏭️ Part III: the other signal — <a href=\"#ch08\">CH 08: Where Logs Live</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 9</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"where-logs-actually-live\">📜 Where Logs Actually Live</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Every container's <b>stdout and stderr</b> is captured by the container runtime and written to a <b>plain file on the node</b>. That's the entire native logging story — and its limits define everything else in Part III.</p>\n<div class=\"term\"><span class=\"p\">$</span> kubectl logs web-x7k2     <span class=\"g\"># the API reads node files FOR you…</span>\n<span class=\"p\">$</span> minikube ssh\n $ ls /var/log/pods/\n<span class=\"y\">default_web-x7k2_<span class=\"c\">e1a2…</span>/api/0.log</span>  <span class=\"g\"># ns_pod_UID/container/N.log\n# (N = restart count — --previous reads N-1! Book 01 · CH 24)</span>\n $ ls /var/log/containers/\nweb-x7k2_default_api-<span class=\"c\">e1a2…</span>.log  <span class=\"g\"># symlinks — stable names for collectors</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Fact</th><th>Consequence</th></tr>\n<tr><td>Logs are <b>node-local files</b></td><td><code>kubectl logs</code> must ask the kubelet of <i>that</i> node — Pod gone from node = logs gone</td></tr>\n<tr><td>Runtime <b>rotates</b> them (containerd: 10Mi × 5 default)</td><td>chatty apps wrap around; old logs vanish silently</td></tr>\n<tr><td>Survives <b>container</b> restarts (per-Pod dir), dies with the <b>Pod</b></td><td>Book 05's three-lives ladder, log edition</td></tr>\n<tr><td>Survives <b>nothing else</b> — no cluster-wide store exists</td><td>node loss / eviction (Book 04 drain!) = history gone — hence collectors (CH 09)</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>The logging manifesto, 12-factor style:</b> your app writes <b>unbuffered to stdout/stderr</b> — no log files inside the container, no rotation logic. The platform (runtime + collector) handles transport and storage. Apps that insist on writing <code>/var/log/app.log</code> inside the container force you into sidecar workarounds (CH 09).</div></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The eviction surprise:</b> you debug an incident, run <code>kubectl delete pod</code> to \"reset\" it — and the evidence dies with the Pod dir. <b>Grab logs before deleting:</b> <code>kubectl logs NAME &gt; incident.log</code>, or better, have a collector already shipping (CH 09–10) so the question never arises.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> container logs are <b>rotating text files on the node</b> — <code>kubectl logs</code> is just a window onto them, and everything you don't ship off-node (CH 09) dies with the Pod, the rotation, or the node itself.</div></div>\n<p>⏭️ Shipping them somewhere safe — <a href=\"#ch09\">CH 09: Collection Patterns</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"collection-patterns-daemonset-sidecar\">🚚 Collection Patterns — DaemonSet · Sidecar</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Node files don't walk to your database by themselves. Two production patterns move them — and you already know the machinery of both.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">Pattern 1 · Node-level agent (DaemonSet) ★ default</div>\n<div class=\"mtree\">every node:\n  🫛 <u>agent</u> <span class=\"g\">(Promtail / Fluent Bit)</span>\n    ├── reads <b>/var/log/pods/**</b> <span class=\"g\">(hostPath mount)</span>\n    ├── attaches metadata: ns, pod, container, node\n    └── ships → Loki / ES / cloud\n<span class=\"g\">one agent covers EVERY pod on the node —\nzero per-app config, app stays ignorant</span></div></div>\n<div class=\"card\">\n<div class=\"zlabel\">Pattern 2 · Sidecar streamer</div>\n<div class=\"mtree\">one pod:\n  🫛 app ──writes──► <u>emptyDir volume</u> <span class=\"g\">(Book 05 · CH 02!)</span>\n  🫛 sidecar ──tails file──► ships to backend\n<span class=\"g\">app CAN'T use stdout? per-app config,\nfiltering, multiple destinations?\nthe sidecar is app-owned plumbing</span></div></div>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th></th><th>📡 DaemonSet agent</th><th>🤝 Sidecar</th></tr>\n<tr><td><b>Setup</b></td><td>once per cluster</td><td>every Pod that needs it</td></tr>\n<tr><td><b>Resource cost</b></td><td>one agent per node (shared)</td><td>multiplied per Pod</td></tr>\n<tr><td><b>Coverage</b></td><td>everything on stdout/stderr — automatic</td><td>only Pods you modified</td></tr>\n<tr><td><b>Special needs</b></td><td>none possible per-app</td><td>file-based logs, per-app parsing, routing</td></tr>\n<tr><td><b>Verdict</b></td><td><b>start here — 90% of clusters</b></td><td>escape hatch for stubborn apps</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Pattern 3 exists and is usually a trap:</b> the app pushes directly to the logging backend (embedded client, async handler). Rejected because: credentials in every app (Book 02 lesson), retry/buffer logic duplicated everywhere, and backend outage now <i>breaks your app's logging path</i> — sometimes its threads. Centralize transport; keep apps dumb.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> ship logs with a <b>DaemonSet agent reading /var/log/pods</b> — one deployment, zero app changes — and reach for the <b>sidecar</b> only when an app refuses to write stdout; never embed shipping clients in the app itself.</div></div>\n<p>⏭️ Where the shipped logs go — <a href=\"#ch10\">CH 10: Loki</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 11</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"loki-prometheus-for-logs\">🪵 Loki — Prometheus for Logs</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Loki (Grafana Labs) is log aggregation with one radical idea: <b>index the labels, never the text.</b> Full-text engines (ELK) index every word — powerful, expensive. Loki asks: <i>\"why index what you never query?\"</i></p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">💰 The trade</div>\n<ul>\n<li><b>10–20× cheaper</b> storage — only metadata is indexed</li>\n<li>Log lines stored <b>compressed as chunks</b> in cheap object storage</li>\n<li>Search = filter by <b>labels first</b>, then grep the few surviving lines at query time</li>\n<li>Trade-off accepted: free-text search across everything is weaker than ELK — in Kubernetes, labels are so good it rarely matters</li>\n</ul></div>\n<div class=\"card\">\n<div class=\"zlabel\">🏷️ The shared label model</div>\n<div class=\"term mini\">Promtail labels a line with:\n<b>namespace · pod · container · node</b>\n<span class=\"g\">— the SAME labels your metrics carry\n(Book 03 · CH 11's service DNS model) —</span>\n<span class=\"p\">CPU spike on pod X in Grafana →\njump to logs of pod X — zero config</span></div></div>\n</div>\n<div class=\"mtree\"><b>Promtail's four-step pipeline</b> <span class=\"g\">(your DaemonSet agent from CH 09, Loki edition)</span>\n├── 1️⃣ <u>Discover</u>  <span class=\"g\">via k8s Service Discovery — every pod on my node</span>\n├── 2️⃣ <u>Tail</u>      <span class=\"g\">/var/log/pods files (CH 08!)</span>\n├── 3️⃣ <u>Label</u>     <span class=\"g\">attach ns/pod/container/node metadata</span>\n└── 4️⃣ <u>Ship</u>      <span class=\"g\">HTTP PUSH batches → Loki's Distributor</span>\n<span class=\"g\">inside Loki: Distributor → Ingester (chunks) → Store → Querier\n— a Log Stream = one unique label combination</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Cardinality is the cardinal sin:</b> every unique label combo = a new stream to index. <code>user_id</code>, <code>request_id</code> as labels → millions of streams → Loki drowns. Labels for <b>bounded, structured</b> dimensions (ns, pod, app, level) — everything variable goes <i>in</i> the line, filtered at query time.</div></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Push vs pull, the asymmetry:</b> Prometheus <b>pulls</b> metrics (CH 06); Promtail <b>pushes</b> logs (files won't offer themselves). Two transport models, one shared label vocabulary — that pairing is the stack's superpower.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Loki is <b>\"Prometheus for logs\"</b> — index only bounded labels, keep raw lines in cheap chunks, let Promtail's DaemonSet do the labeling — and the same label model makes logs and metrics correlatable out of the box.</div></div>\n<p>⏭️ The window onto all of it — <a href=\"#ch11\">CH 11: Grafana</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 12</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"grafana-the-unified-pane\">📊 Grafana — The Unified Pane</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>Grafana stores <b>nothing</b>. It's a stateless query-and-render layer over your data sources — the glass pane in front of Prometheus (metrics) and Loki (logs). Empty datasources = empty dashboard; the data always lives in the backends.</p>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">The classic debug flow — all signals, one pane</div>\n<div class=\"rowc\">\n<div class=\"kchip\">🚨 Metric alert<small> \"error rate jumped\"</small></div>\n<span class=\"harr\">──►</span>\n<div class=\"kchip\">📈 Prometheus panel<small> confirm · since when</small></div>\n<span class=\"harr\">──►</span>\n<div class=\"kchip\">🪵 Loki panel<small> same labels → the exception line</small></div>\n</div>\n<p>label jump: <code>{namespace=\"shop\", pod=\"api-x7k2\"}</code> — metric query and log query share the selector</p>\n</div>\n<ul>\n<li>🔌 <b>Datasources</b> — Prometheus, Loki, and dozens more; kube-prometheus-stack wires them in at install (Lab 3)</li>\n<li>📈 <b>Dashboards</b> — panels of PromQL/LogQL; community dashboards (node full-coverage, k8s cluster views) import by ID in seconds</li>\n<li>📜 <b>Dashboards as code</b> — export JSON, version in Git next to your manifests — observability joining your declarative world</li>\n<li>🚨 <b>Alerting UI</b> — Grafana can evaluate alert rules too; deep setups keep alerting in Prometheus/Alertmanager (CH 06) and use Grafana for visualization + triage</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The datasources-conflict trap:</b> kube-prometheus-stack deploys Grafana <i>itself</i> (it's part of the bundle) and auto-configures its Prometheus datasource. If you later install Grafana separately and wonder why panels are empty — you're looking at <b>a different Grafana with no datasources</b>. One pane per cluster (or deliberately many, each configured).</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Grafana is the <b>stateless window</b> — metrics and logs stay in Prometheus/Loki, and its value is the shared-label jump from \"the graph looks wrong\" to \"here's the exact exception line\" in seconds.</div></div>\n<p>⏭️ Speaking both languages — <a href=\"#ch12\">CH 12: PromQL &amp; LogQL</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch12\">next ▶</a></span><span>Page 13</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 12</span><h2 id=\"promql-amp-logql-first-queries\">🗣️ PromQL &amp; LogQL — First Queries</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Both query languages share DNA (that's deliberate — Loki's LogQL is <i>designed</i> to feel like PromQL). Learn the four moves and you can interrogate both signals.</p>\n<h3 id=\"promql-four-moves\">📈 PromQL — four moves</h3>\n<div class=\"term\"><span class=\"g\"># 1 · SELECT — by name + label matchers</span>\ncontainer_cpu_usage_seconds_total{namespace=<span class=\"m\">\"shop\"</span>}\n<span class=\"g\"># 2 · RATE — counters need a rate over a window</span>\n<span class=\"c\">rate</span>(http_requests_total[<span class=\"y\">5m</span>])\n<span class=\"g\"># 3 · AGGREGATE — sum/avg by label dimension</span>\n<span class=\"c\">sum by</span> (pod) (<span class=\"c\">rate</span>(container_cpu_usage_seconds_total\n  {namespace=<span class=\"m\">\"shop\"</span>, container!=<span class=\"m\">\"\"</span>} [<span class=\"y\">5m</span>]))\n<span class=\"g\"># 4 · CONDITION — the alert-shaped question</span>\n<span class=\"c\">sum by</span> (pod) (<span class=\"c\">rate</span>(http_requests_total{code=~<span class=\"m\">\"5..\"</span>}[<span class=\"y\">5m</span>]))\n  / <span class=\"c\">sum by</span> (pod) (<span class=\"c\">rate</span>(http_requests_total[<span class=\"y\">5m</span>])) &gt; <span class=\"y\">0.05</span></div>\n<h3 id=\"logql-same-shape-logs\">🪵 LogQL — same shape, logs</h3>\n<div class=\"term\"><span class=\"g\"># selector (LABELS ONLY — CH 10) then line filters then parse:</span>\n{namespace=<span class=\"m\">\"shop\"</span>, pod=~<span class=\"m\">\"web-.*\"</span>}\n  <span class=\"y\">|=</span> <span class=\"m\">\"ERROR\"</span>             <span class=\"g\"># line contains</span>\n  <span class=\"y\">!=</span> <span class=\"m\">\"health\"</span>           <span class=\"g\"># exclude noise</span>\n<span class=\"g\"># metrics FROM logs — count matches per minute:</span>\n<span class=\"c\">sum by</span> (pod) (<span class=\"c\">rate</span>({namespace=<span class=\"m\">\"shop\"</span>} <span class=\"y\">|=</span> <span class=\"m\">\"Timeout\"</span> [<span class=\"y\">5m</span>]))\n<span class=\"g\"># and the correlation close (CH 11):</span>\n<span class=\"g\"># panel 1: rate(http_requests_total{pod=~\"web-.*\"}[5m])</span>\n<span class=\"g\"># panel 2: {pod=~\"web-.*\"} |= \"ERROR\"   ← same pod regex!</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Counter law:</b> counters only go up (restarts reset them) — <b>always</b> wrap them in <code>rate()</code> over a window; the raw value is meaningless across restarts. Gauges (memory, queue depth) you query raw. This one rule separates useful dashboards from lying ones.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> both languages are <b>select → (rate) → aggregate → condition</b> — learn it once on metrics, reuse the shape on logs, and let shared labels stitch the two into one investigation. Lab 4 runs these live.</div></div>\n<p>⏭️ Part V: the operational paper trail — <a href=\"#ch13\">CH 13: Events &amp; Audit</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch13\">next ▶</a></span><span>Page 14</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 13</span><h2 id=\"events-amp-audit-logging\">📋 Events &amp; Audit Logging</h2><span class=\"dbadge\">🟢 5 MIN</span></div>\n<p>Two different diaries. <b>Events</b>: what the controllers did to your objects (you've read them in every <code>describe</code> since Book 01). <b>Audit log</b>: what <i>humans and clients</i> did to the API — the who-did-what record.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">📋 Events — the controller chronicle</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get events --sort-by=<span class=\"y\">.lastTimestamp</span>\n<span class=\"y\">LAST SEEN  TYPE     REASON     OBJECT</span>\n12s        <span class=\"r\">Warning</span>  BackOff    pod/web-x7k2\n4m         <span class=\"p\">Normal</span>   Scheduled  pod/web-x7k2\n<span class=\"g\"># Normal = information · Warning = attention\n# TTL ~1 hour — they EXPIRE. not an archive.\n# per-namespace scope (Book 01 scoping!)</span></div>\n<p>Every debugging chapter used them — now you know their lifecycle: generated by controllers/kubelet, aggregated per object, <b>ephemeral</b>. For incident forensics, ship them (EventExporter → Loki) or lose them.</p></div>\n<div class=\"card\">\n<div class=\"zlabel\">🪪 Audit log — the API dashcam</div>\n<div class=\"term mini\"><span class=\"g\"># apiserver feature — OFF by default.\n# you supply a policy (stages):</span>\n<span class=\"c\">who</span>:    user / serviceaccount  <span class=\"g\">(Book 02!)</span>\n<span class=\"c\">what</span>:   verb + resource       <span class=\"g\">delete secrets…</span>\n<span class=\"c\">when</span>:   timestamp + source IP\n<span class=\"c\">result</span>: allowed / denied      <span class=\"g\">(RBAC verdicts)</span>\n<span class=\"g\"># policy levels: None → Metadata →\n# Request → RequestResponse (noisy!)</span></div>\n<p>The record that answers \"who deleted the production namespace?\" — RBAC says who <i>may</i>; audit says who <i>did</i>. Compliance surveys live here. Concept-level for us; enablement is cluster-lifecycle work (Book 09).</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Triage pairing:</b> something's wrong → <code>kubectl get events --sort-by=.lastTimestamp</code> (what did the <i>system</i> do) + audit log (what did the <i>humans</i> do right before). Between the two diaries, almost every \"nobody changed anything\" mystery resolves — <i>somebody</i> did, and the dashcam has the plate number.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> events are the <b>system's own short-term diary</b> (1-hour TTL — read them fast), audit logging the <b>opt-in API dashcam</b> recording every identity, verb, and verdict — together they cover both \"what happened to my workload\" and \"who touched my cluster.\"</div></div>\n<p>⏭️ Everything assembled — <a href=\"#ch14\">CH 14: The Failure Playbook</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch12\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch14\">next ▶</a></span><span>Page 15</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 14</span><h2 id=\"the-cluster-scope-failure-playbook\">🚑 The Cluster-Scope Failure Playbook</h2><span class=\"dbadge\">🟡 6 MIN · FINALE</span></div>\n<p>Books 01–06 debugged <i>one Pod</i>. Real incidents are cluster-shaped: whole namespaces Pending, every DNS lookup dying, a node evacuating itself. The playbook — first move for each signature (every row is a callback):</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Signature</th><th>Probable cause</th><th>First move</th></tr>\n<tr><td><b>Everything in one ns → Pending</b></td><td>ResourceQuota exhausted (B02) or no node fits (B04 funnel)</td><td><code>kubectl describe quota -n ns</code> · read a Pod's events</td></tr>\n<tr><td><b>All pods ImagePullBackOff, one ns</b></td><td>imagePullSecrets missing/wrong (B02 · CH 06)</td><td><code>kubectl get sa default -o yaml</code> → check secret</td></tr>\n<tr><td><b>One node NotReady, pods evacuating</b></td><td>kubelet/heartbeat lost → NoExecute taints (B04 · CH 05)</td><td><code>kubectl describe node N</code> → conditions + taints</td></tr>\n<tr><td><b>ALL DNS failing cluster-wide</b></td><td>CoreDNS pods down (B03 · CH 11–12)</td><td><code>kubectl get pods -n kube-system -l k8s-app=kube-dns</code></td></tr>\n<tr><td><b>Ingress: everything 404/timeout</b></td><td>controller Pod down, or rulebook orphaned (B03 · CH 04)</td><td><code>kubectl get pods -n ingress-nginx</code> · <code>get ingress</code> → ADDRESS?</td></tr>\n<tr><td><b>Random OOMKills across teams</b></td><td>node memory pressure → eviction by QoS (B02 · CH 15)</td><td><code>kubectl top nodes</code> · check node <code>memory-pressure</code> taint</td></tr>\n<tr><td><b>API slow/5xx for everyone</b></td><td>etcd struggling / quorum at risk (B01 · CH 08)</td><td>check static-pod etcd on CP nodes (B04 · CH 11) · <code>events</code></td></tr>\n<tr><td><b>PVs stuck Pending cluster-wide</b></td><td>provisioner/sc issues (B05 · CH 04/07)</td><td><code>kubectl get sc</code> → default present? · check CSI pods</td></tr>\n</table></div>\n<div class=\"mtree\"><b>The universal triage reflex</b> <span class=\"g\">(before any of the rows above):</span>\n1 · <u>kubectl get nodes</u>            <span class=\"g\">is the fleet itself healthy?</span>\n2 · <u>kubectl get pods -A</u>           <span class=\"g\">which scope? one ns / one node / everywhere?</span>\n3 · <u>kubectl get events -A --sort-by=.lastTimestamp</u>  <span class=\"g\">the chronicle (CH 13)</span>\n<span class=\"g\">scope FIRST — \"one namespace\" and \"one node\" are different books of the same incident.</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Scope is the diagnosis:</b> one Pod → Book 01's toolbox. One namespace → quota/secrets/RBAC. One node → taints/kubelet/disk. Everything → control plane, DNS, or the network fabric. Nine books of knowledge, organized by blast radius.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> cluster incidents resolve by <b>scope-first triage</b> — nodes, then pods -A, then events — and the playbook above turns each signature into the exact chapter of this series that owns it. Lab 2 drills the reflex.</div></div>\n<p>⏭️ Prove all of it with your hands — <a href=\"#lab1\">Part VI: Labs</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch13\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab1\">labs ▶</a></span><span>Page 16</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"probes-that-bite\">🔬 Probes That Bite</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · A pod whose health is a file — liveness</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: Pod\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: probe-lab }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">containers</span>:\n  - <span class=\"c\">name</span>: c\n    <span class=\"c\">image</span>: busybox:1.36\n    <span class=\"c\">command</span>: [<span class=\"m\">sh</span>,<span class=\"m\">-c</span>,<span class=\"m\">'touch /tmp/healthy; sleep 9999'</span>]\n    <span class=\"c\">livenessProbe</span>:\n      <span class=\"c\">exec</span>: { <span class=\"c\">command</span>: [<span class=\"m\">cat</span>, <span class=\"m\">/tmp/healthy</span>] }\n      <span class=\"c\">periodSeconds</span>: <span class=\"y\">5</span>\n      <span class=\"c\">failureThreshold</span>: <span class=\"y\">2</span>\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl get pod probe-lab  <span class=\"g\"># Running, READY 1/1, 0 restarts</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Break it — the kubelet fights back</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl exec probe-lab -- rm /tmp/healthy\n<span class=\"p\">$</span> kubectl get pod probe-lab -w\n<span class=\"y\">probe-lab  Running  0</span>\nprobe-lab  Running  <span class=\"r\">1</span>  <span class=\"g\"># 2 fails → KILLED &amp; restarted (fresh file! CH 02)</span>\n<span class=\"p\">$</span> kubectl describe pod probe-lab | <span class=\"c\">grep</span> -A2 Events | <span class=\"c\">tail</span> -2\n<span class=\"y\">Container c failed liveness probe, will be restarted</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 READINESS — THE GATE</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl patch pod probe-lab \\\n  <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> <span class=\"m\">'{\"metadata\":{\"labels\":{\"app\":\"g\"}}}'</span>\n<span class=\"p\">$</span> kubectl expose pod probe-lab \\\n  --port=80 --name=gate\n<span class=\"p\">$</span> kubectl get endpoints gate\n<span class=\"y\">gate  <span class=\"p\">10.244.0.5:80</span></span>\n<span class=\"g\"># remove the health file again →\n# readiness (same probe) fails →</span>\n<span class=\"p\">$</span> kubectl get endpoints gate\n<span class=\"y\">gate  <span class=\"r\">&lt;none&gt;</span>  <span class=\"g\"># GATED — pod still\n# Running, zero restarts!\n# (readiness ≠ liveness, CH 03)</span></span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 READ THE RESTART STORY</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl get pod probe-lab\n<span class=\"y\">READY  RESTARTS</span>\n1/1    <span class=\"y\">2</span>  <span class=\"g\"># each restart =\n# the reflex working.\n# RESTARTS ≠ broken —\n# it's the cure being\n# applied (CH 01!)</span></div></div>\n</div>\n<p><b>Proved:</b> liveness kills the undead; readiness gates traffic without touching the process. <b>Teardown:</b> <code>kubectl delete pod probe-lab svc/gate</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#ch14\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab2\">next ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"top-amp-events-triage\">🔬 Top &amp; Events Triage</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · The pulse — metrics-server</div>\n<div class=\"term mini\"><span class=\"p\">$</span> minikube addons enable metrics-server\n<span class=\"p\">$</span> kubectl top nodes  <span class=\"g\"># give it ~60s after enabling</span>\n<span class=\"y\">NAME      CPU(cores)  CPU%   MEMORY(bytes)  MEMORY%</span>\nminikube  350m        17%    1800Mi         46%\n<span class=\"p\">$</span> kubectl top pods -A --sort-by=memory | <span class=\"c\">head</span> -5\n<span class=\"g\"># the whole cluster, ranked by appetite —\n# your right-sizing shortlist (Book 06 · CH 08)</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Cause a failure, then read the chronicle</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create deploy ghost --image=nginx:<span class=\"y\">1.999</span>\n<span class=\"p\">$</span> kubectl get events --sort-by=<span class=\"y\">.lastTimestamp</span> | <span class=\"c\">grep</span> -i ghost\n<span class=\"r\">Warning  Failed  Failed to pull image \"nginx:1.999\"</span>\n<span class=\"r\">Warning  BackOff  Back-off pulling image</span>\n<span class=\"g\"># the incident wrote its own report —\n# BEFORE you ran a single describe (CH 13)</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · The scope-first reflex (CH 14)</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get nodes  <span class=\"g\"># 1 · fleet healthy?</span>\n<span class=\"p\">$</span> kubectl get pods -A | <span class=\"c\">grep</span> -v Running  <span class=\"g\"># 2 · blast radius?</span>\n<span class=\"p\">$</span> kubectl get events -A --sort-by=.lastTimestamp | <span class=\"c\">head</span> -8 <span class=\"g\"># 3 · chronicle</span>\n<span class=\"g\"># three commands, scope identified, playbook row selected —\n# the CH 14 reflex, now muscle memory</span></div></div>\n<p><b>Proved:</b> live usage via top, self-writing incident chronicles via events, and the universal triage reflex. <b>Teardown:</b> <code>kubectl delete deploy ghost</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 07 · Observability &amp; Operations</span><span><a href=\"#lab1\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab3\">next ▶</a></span><span>Page 18</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"install-the-stack-helm-preview\">🔬 Install the Stack (Helm Preview)</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Honesty first:</b> the stack ships as <b>Helm charts</b> — Book 08's subject. Today you run four commands as a <i>preview</i>; Book 08 explains what every flag did. Needs ~3GB free in minikube: <code>minikube start --memory=6144</code> if tight.</div></div>\n<div class=\"labstep\"><div>STEP 1 · Metrics + logs + pane — four commands</div>\n<div class=\"term mini\"><span class=\"p\">$</span> curl -fsSL https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3 | bash\n<span class=\"p\">$</span> helm repo add prometheus-community https://prometheus-community.github.io/helm-charts\n<span class=\"p\">$</span> helm repo add grafana https://grafana.github.io/helm-charts &amp;&amp; helm repo update\n<span class=\"p\">$</span> helm install mon prometheus-community/kube-prometheus-stack\n<span class=\"p\">$</span> helm install loki grafana/loki-stack \\\n    <span class=\"y\">--set</span> promtail.enabled=<span class=\"y\">true</span>  <span class=\"g\"># ← the CH 09 DaemonSet agent!</span>\n<span class=\"p\">$</span></div></div></div>","toc":[{"id":"observability-amp-operations","text":"OBSERVABILITY &amp;OPERATIONS","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"running-healthy","text":"🩺 Running ≠ Healthy","level":2},{"id":"the-three-pillars-this-book-covers-and-the-fourth","text":"🔭 The three pillars this book covers (and the fourth)","level":3},{"id":"liveness-probes-restart-the-stuck","text":"💀 Liveness Probes — Restart the Stuck","level":2},{"id":"readiness-the-traffic-gate","text":"🚦 Readiness — The Traffic Gate","level":2},{"id":"startup-probes-amp-probe-mechanics","text":"🐣 Startup Probes &amp; Probe Mechanics","level":2},{"id":"metrics-server-amp-kubectl-top","text":"📊 Metrics Server &amp; kubectl top","level":2},{"id":"prometheus-the-pull-model","text":"🔥 Prometheus — The Pull Model","level":2},{"id":"the-exporter-cast-who-exposes-what","text":"🛰️ The Exporter Cast — Who Exposes What","level":2},{"id":"servicemonitor-declarative-scrape-config","text":"🎯 ServiceMonitor — declarative scrape config","level":3},{"id":"where-logs-actually-live","text":"📜 Where Logs Actually Live","level":2},{"id":"collection-patterns-daemonset-sidecar","text":"🚚 Collection Patterns — DaemonSet · Sidecar","level":2},{"id":"loki-prometheus-for-logs","text":"🪵 Loki — Prometheus for Logs","level":2},{"id":"grafana-the-unified-pane","text":"📊 Grafana — The Unified Pane","level":2},{"id":"promql-amp-logql-first-queries","text":"🗣️ PromQL &amp; LogQL — First Queries","level":2},{"id":"promql-four-moves","text":"📈 PromQL — four moves","level":3},{"id":"logql-same-shape-logs","text":"🪵 LogQL — same shape, logs","level":3},{"id":"events-amp-audit-logging","text":"📋 Events &amp; Audit Logging","level":2},{"id":"the-cluster-scope-failure-playbook","text":"🚑 The Cluster-Scope Failure Playbook","level":2},{"id":"probes-that-bite","text":"🔬 Probes That Bite","level":2},{"id":"top-amp-events-triage","text":"🔬 Top &amp; Events Triage","level":2},{"id":"install-the-stack-helm-preview","text":"🔬 Install the Stack (Helm Preview)","level":2}],"words":5534,"assets":[]};